import itertools,math
import manual_solutions as author
def put(n,steps,errors):
 if n==15:steps=[s.replace(r'\n\n','\n\n') for s in steps]
 author.add('DM2T',f'006-{n:03}',steps,errors,'逐小问核对元素层级、集合运算、双向证明、反例、容斥与图示的各原子区域。')
def example(n,steps,errors):
 author.add_example('DM2T',n,steps,errors,'逐步展开元素关系或运算法则，核对所有计数交项与充分必要方向。')
def T(S):
 if not isinstance(S,(set,frozenset)):return str(S)
 if not S:return r'\varnothing'
 def key(x):return (0,x) if isinstance(x,int) else (1,T(x))
 return r'\{'+','.join(T(x) for x in sorted(S,key=key))+r'\}'
def power(S):
 a=list(S);return frozenset(frozenset(c) for n in range(len(a)+1) for c in itertools.combinations(a,n))
def result(label,S):return label+' $$'+T(S)+'.$$'
def sieve(N,divisors):
 out=[f'在1至{N}内被d整除的数为d、2d至⌊'+str(N)+'/d⌋d，共⌊'+str(N)+'/d⌋个。交集需同时整除，对应最小公倍数，而不一定是各数直接相乘。']
 total=0
 for k in range(1,len(divisors)+1):
  entries=[]
  for ds in itertools.combinations(divisors,k):
   d=math.lcm(*ds);count=N//d;total+=(-1)**(k+1)*count
   entries.append(r'\lfloor '+str(N)+'/'+str(d)+r'\rfloor='+str(count))
  out+=['第'+str(k)+'重交项逐个为 $$'+r',\quad '.join(entries)+r'.$$容斥中本层符号为'+('加' if k%2 else '减')+'。']
 assert total==sum(any(v%d==0 for d in divisors) for v in range(1,N+1))
 out+=['因此至少被其中一个整除的共有'+str(total)+'个，三者均不整除则为'+str(N)+'−'+str(total)+'='+str(N-total)+'个。']
 return out

